/** The base class of a mind id: `e4b-2` → `e4b` (C-01). */
export const baseOf = (id) => String(id).replace(/-\d+$/, '')
/** Mass `m = bytes ÷ 5,154,939,136` (the E4B = 1); a process has m = 1 (A3 §2). */
export const massOf = (bytes) => (bytes > 0 ? bytes / E4B_BYTES : 1)
/** The travel factor `mT = 0.6 + 0.5 √m` (travel, loops, float). */
export const travelFactor = (m) => 0.6 + 0.5 * Math.sqrt(m)
/** The rise factor `mR = 0.7 + 0.4 √m` (rise, sink). */
export const riseFactor = (m) => 0.7 + 0.4 * Math.sqrt(m)
/** The float period, seconds: `max(4 s, 3.5 s × mT)` (RULINGS C-39; M-21). */
export const floatPeriod = (m) => Math.max(4, 3.5 * travelFactor(m))
/** A run's words for a label (floorModel.js:118 `runWords`, kept). */
export const runWords = (n) => String(n || '').replace(/^cart /, '').replace(/^wo:/, 'work order ')
/** The feed's four hues for an event line (floorEvents.js:10 `SEV`, kept). */
export const SEV = Object.freeze({ info: 'N-STEEL', good: 'N-WHITE', warn: 'AMBER', fault: 'RED' })

