/**
 * The ceremony for a transition from a kind's table of `[from, to, ceremony]` rows: `*` any state, `busy.*` a group, `(none)`
 * the first appearance; the first row that matches wins; null is a plain cut (A3 §5).
 * @param {!Array<!Array<string>>} table @param {?string} from @param {string} to
 * @return {?string}
 */
export function ceremonyOf(table, from, to) {
  const hit = (pat, s) => pat === '*' || pat === s || (pat.endsWith('.*') && s != null && s.startsWith(pat.slice(0, -1))) || (pat === '(none)' && s == null)
  for (const [f, t, c] of table) if (hit(f, from) && hit(t, to)) return c
  return null
}

/**
 * @typedef {Object} Form one channel that moves (A4 §6.1 `forms[]`)
 * @property {string} channel @property {string} shape @property {?string} hue a `HUES` name, 'neutral', 'own' or null
 * @property {string} amplitude text with units @property {?number} blinkHz @property {?string} blinkClass ambient | attention | warn | fail
 * @property {?number} periodMs @property {?number} durationMs @property {?string} curve ENTER | EXIT | GLIDE | LIN | RCOS | STEP | SPRING
 * @property {boolean} status a mark that carries meaning @property {boolean} continuous @property {?string} ramp 'luminance-monotonic'
 * @property {number=} repeat @property {number=} gapMs @property {number=} coalesceMs record-driven beats coalesce to ≥ 500 ms
 * @property {number=} revPerS a spin @property {string=} sender the identity whose hue the form borrows (the seal, a droplet)
 */
/**
 * @typedef {Object} Step one timeline step (A4 §6.1 `timeline[]`)
 * @property {number} atMs @property {string} channel @property {string} step
 * @property {(number|string)=} durationMs a number, or 'real' when the record times it @property {string=} field the field that times a 'real' step
 */
/**
 * @typedef {Object} VocabularyRow A4 §6.1, frozen on day 1, plus the five fields of RULINGS §1(c)
 * @property {string} id V-### @property {string} actor @property {string} state @property {?string} cause
 * @property {{kinds: !Array<string>, fields: !Array<string>, rule: string, onDelayMs: number, offDelayMs: number}} record
 * @property {!Array<!Form>} forms @property {!Array<!Step>} timeline @property {!Array<string>} tokens
 * @property {number} movers @property {number} flashers @property {number} overshoot @property {number} bouncePct @property {number} squashPct
 * @property {?number} exitRatio @property {?string} entrance the entrance row an exit row names (L14) @property {number} fixedMs
 * @property {boolean} massScaled @property {{card: string, tab: string, record: string}} click A9's card kinds and tabs (C-29)
 * @property {string} reducedMotion @property {string} lite @property {!Array<string>} source
 * @property {?string} ceremonyIn @property {?string} ceremonyOut @property {?string} sound @property {string} degraded
 * @property {?{priority: number, dwellMs: number}} camera @property {string} label @property {string} chip @property {string} strip
 * @property {?string} yieldsTo the row this row's flasher yields to (L5)
 */

/**
 * One form with the defaults A4 §6.1 names.
 * @param {string} channel @param {string} shape @param {?string} hue @param {string} amplitude @param {!Object=} o
 * @return {!Form}
 */
export function form(channel, shape, hue, amplitude, o = {}) {
  return { channel, shape, hue, amplitude, blinkHz: null, blinkClass: null, periodMs: null, durationMs: null, curve: null, status: false, continuous: false, ramp: null, ...o }
}
/**
 * One timeline step.
 * @param {number} atMs @param {string} channel @param {string} step @param {(number|string)=} durationMs @param {string=} field
 * @return {!Step}
 */
export const step = (atMs, channel, step_, durationMs, field) => ({ atMs, channel, step: step_, durationMs, field })

/**
 * The fixed ms of a timeline per stage (L13): stages split at a 'real' step; each is the latest end of its fixed steps. A rhythm
 * is not choreography (A4 §1: AMB, WARN and FAIL are rhythms a form declares by `blinkClass`), so a step that plays a form's
 * rhythm (`blink ×3` on a WARN or FAIL form; any step on an AMB form) is left out of the stage it sits in.
 * @param {!Array<!Step>} timeline @param {!Array<!Form>=} forms
 */
export function stagesOf(timeline, forms = []) {
  const stages = [[]]
  const rhythm = (s) => forms.some((f) => f.channel === s.channel && f.blinkClass && (f.blinkClass === 'ambient' || /^blink/.test(s.step)))
  for (const s of timeline) { if (s.durationMs === 'real') stages.push([]); else if (!rhythm(s)) stages[stages.length - 1].push(s) }
  return stages.map((steps) => steps.reduce((m, s) => Math.max(m, s.atMs - (steps[0]?.atMs ?? 0) + (typeof s.durationMs === 'number' ? s.durationMs : 0)), 0))
}

/**
 * One row with the defaults A4 §6.1 names; `rec` is `{kinds, fields, rule, on, off}`, `click` is `[card, tab, record]`.
 * @param {string} id @param {string} actor @param {string} state @param {?string} cause @param {!Object} rec
 * @param {!Array<!Form>} forms @param {!Array<!Step>} timeline @param {!Object} o the rest
 * @return {!VocabularyRow}
 */
export function row(id, actor, state, cause, rec, forms, timeline, o) {
  const stages = stagesOf(timeline, forms)
  const [card, tab, record] = o.click
  return {
    id, actor, state, cause,
    record: { kinds: rec.kinds, fields: rec.fields || [], rule: rec.rule, onDelayMs: rec.on || 0, offDelayMs: rec.off || 0 },
    forms, timeline, tokens: o.tokens || [], movers: o.movers || 0,
    flashers: o.flashers ?? forms.filter((f) => f.blinkClass && f.blinkClass !== 'ambient').length,
    overshoot: o.overshoot || 0, bouncePct: o.bouncePct || 0, squashPct: o.squashPct || 0, exitRatio: o.exitRatio ?? null,
    entrance: o.entrance ?? null, fixedMs: o.fixedMs ?? Math.max(0, ...stages), stages, massScaled: o.massScaled || false,
    click: { card, tab, record }, reducedMotion: o.reduced || 'same', lite: o.lite || 'same', source: o.source || [],
    ceremonyIn: o.ceremonyIn ?? null, ceremonyOut: o.ceremonyOut ?? null, sound: o.sound ?? null, degraded: o.degraded || 'D1',
    camera: o.camera ?? null, label: o.label || '', chip: o.chip || '', strip: o.strip || '', yieldsTo: o.yieldsTo ?? null,
  }
}

const F = form
const S = step
const WARN = (channel, shape, amplitude, o = {}) => F(channel, shape, 'AMBER', amplitude, { blinkHz: 0.6, blinkClass: 'warn', status: true, ...o })
const FAIL = (channel, shape, amplitude, o = {}) => F(channel, shape, 'RED', amplitude, { blinkHz: 1.5, blinkClass: 'fail', status: true, ...o })
const ATT = (channel, shape, amplitude, o = {}) => F(channel, shape, 'AMBER', amplitude, { blinkHz: 0.5, blinkClass: 'attention', status: true, ...o })
const AMB = (channel, shape, hue, amplitude, periodMs, o = {}) => F(channel, shape, hue, amplitude, { blinkHz: 1000 / periodMs, blinkClass: 'ambient', periodMs, curve: 'RCOS', ...o })
const REDS = (channel, shape, amplitude, o = {}) => F(channel, shape, 'RED', amplitude, { status: true, ...o })
const AMBS = (channel, shape, amplitude, o = {}) => F(channel, shape, 'AMBER', amplitude, { status: true, ...o })
const GHOST = (channel, amplitude, o = {}) => F(channel, 'dashed', 'N-GHOST', amplitude, { status: true, ...o })
const TICK = (channel, amplitude, o = {}) => F(channel, 'tick', 'N-WHITE', amplitude, { durationMs: 120, coalesceMs: 500, ...o })
const FAILSEQ = (channel) => [S(0, channel, 'hold', 150), S(150, channel, 'close', 240), S(390, channel, 'blink ×3', 2000)]
const MIND = { kinds: ['mind.turn.phase', 'mind.slot'], fields: ['phase', 'tokens', 'tps', 'busy', 'n-decoded'] }
const R = (o) => o

